INSERT INTO "organization" ("id", "name", "role", "period", "description", "website", "order", "logoUrl", "images", "proofUrl", "slug", "createdAt", "updatedAt", "showOnHome") VALUES (14, 'GDG USU (Google Developer Groups Universitas Sumatera Utara)', 'Member', '2025 – Sekarang', 'Mengikuti kegiatan komunitas teknologi yang berfokus pada pengembangan keterampilan pemrograman, software development, dan teknologi digital melalui workshop, seminar, serta networking dengan praktisi industri teknologi.', 'https://www.instagram.com/gdgoc.usu/', 2, 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRmOHG99Gglye2L1mfmZe9aEFe9cY5v2Mf6hg&s', NULL, NULL, 'org-14', '2026-04-25T23:23:34.829921+00:00', '2026-04-26T02:20:32.179916+00:00', true);
INSERT INTO "organization" ("id", "name", "role", "period", "description", "website", "order", "logoUrl", "images", "proofUrl", "slug", "createdAt", "updatedAt", "showOnHome") VALUES (15, 'HIPMI PT USU (Himpunan Pengusaha Muda Indonesia Perguruan Tinggi USU)', 'Member', '2025 – Sekarang', 'Berpartisipasi dalam kegiatan pengembangan kewirausahaan mahasiswa, pelatihan bisnis, seminar entrepreneur, serta membangun relasi dengan pengusaha muda di lingkungan kampus dan regional.', 'https://www.instagram.com/hipmiptusu/', 3, 'https://upload.wikimedia.org/wikipedia/commons/3/31/Logo_HIPMI.png', NULL, NULL, 'org-15', '2026-04-25T23:23:34.829921+00:00', '2026-04-26T02:20:32.179916+00:00', true);
