INSERT INTO "article" ("id", "title", "slug", "content", "imageUrl", "tags", "published", "createdAt", "updatedAt", "images", "excerpt", "category", "showOnHome") VALUES (7, 'Memulai Karir sebagai Full Stack Developer di Usia Muda', 'memulai-karir-fullstack', 'Memulai karir di bidang teknologi di usia muda bukanlah hal yang mustahil. Mulailah dari dasar: HTML, CSS, JavaScript.', 'https://uuybelgxovlgozgizith.supabase.co/storage/v1/object/public/portofolio/dummy/blog_career.png', NULL, true, '2026-04-26T02:29:19.66', '2026-04-26T02:29:19.66', NULL, 'Panduan lengkap bagi pemuda yang ingin memulai karir sebagai full stack developer dari nol.', 'Karir', true);
INSERT INTO "article" ("id", "title", "slug", "content", "imageUrl", "tags", "published", "createdAt", "updatedAt", "images", "excerpt", "category", "showOnHome") VALUES (8, 'Supabase vs Firebase: Mana yang Lebih Cocok?', 'supabase-vs-firebase', 'Dua platform BaaS populer ini memiliki kelebihan masing-masing. Supabase berbasis PostgreSQL open-source, Firebase dari Google dengan NoSQL.', 'https://uuybelgxovlgozgizith.supabase.co/storage/v1/object/public/portofolio/dummy/blog_tech.png', NULL, true, '2026-04-26T02:29:19.66', '2026-04-26T02:29:19.66', NULL, 'Analisis lengkap kelebihan dan kekurangan Supabase vs Firebase untuk project modern.', 'Teknologi', true);
INSERT INTO "article" ("id", "title", "slug", "content", "imageUrl", "tags", "published", "createdAt", "updatedAt", "images", "excerpt", "category", "showOnHome") VALUES (9, 'Belajar Next.js 14 dari Nol untuk Pemula', 'belajar-nextjs-14', 'Next.js adalah framework React yang memungkinkan server-side rendering, static generation, dan banyak fitur production-ready out of the box.', 'https://uuybelgxovlgozgizith.supabase.co/storage/v1/object/public/portofolio/dummy/blog_tech.png', NULL, true, '2026-04-26T02:29:19.66', '2026-04-26T02:29:19.66', NULL, 'Tutorial step-by-step belajar Next.js 14 dengan App Router untuk pemula absolut.', 'Tutorial', true);
INSERT INTO "article" ("id", "title", "slug", "content", "imageUrl", "tags", "published", "createdAt", "updatedAt", "images", "excerpt", "category", "showOnHome") VALUES (10, 'Pentingnya Soft Skill bagi Seorang Developer', 'softskill-penting-developer', 'Komunikasi, manajemen waktu, dan kemampuan berkolaborasi adalah soft skill yang sering diremehkan namun sangat krusial.', 'https://uuybelgxovlgozgizith.supabase.co/storage/v1/object/public/portofolio/dummy/blog_career.png', NULL, true, '2026-04-26T02:29:19.66', '2026-04-26T02:29:19.66', NULL, 'Mengapa komunikasi dan kepemimpinan sama pentingnya dengan kemampuan coding.', 'Karir', true);
INSERT INTO "article" ("id", "title", "slug", "content", "imageUrl", "tags", "published", "createdAt", "updatedAt", "images", "excerpt", "category", "showOnHome") VALUES (11, 'Membangun Portofolio Digital yang Menarik', 'membangun-portofolio-digital', 'Portofolio adalah wajah profesional kamu di dunia digital. Ini yang pertama dilihat klien atau recruiter sebelum memutuskan untuk menghubungimu.', 'https://uuybelgxovlgozgizith.supabase.co/storage/v1/object/public/portofolio/dummy/blog_career.png', NULL, true, '2026-04-26T02:29:19.66', '2026-04-26T02:29:19.66', NULL, 'Cara membangun portofolio digital yang profesional dan meninggalkan kesan mendalam.', 'Personal', true);
INSERT INTO "article" ("id", "title", "slug", "content", "imageUrl", "tags", "published", "createdAt", "updatedAt", "images", "excerpt", "category", "showOnHome") VALUES (12, 'Tips Time Management untuk Mahasiswa Aktif', 'tips-time-management-mahasiswa', 'Menjadi aktif di organisasi sambil menjaga IPK adalah tantangan nyata. Berikut strategi yang telah terbukti efektif: time blocking dan prioritas tugas.', 'https://uuybelgxovlgozgizith.supabase.co/storage/v1/object/public/portofolio/dummy/blog_tech.png', NULL, true, '2026-04-26T02:29:19.66', '2026-04-26T02:29:19.66', NULL, 'Strategi manajemen waktu yang efektif bagi mahasiswa yang aktif berorganisasi.', 'Lifestyle', true);
